-- Overview:
-- This file extends the existing Collider DB database by adding
-- five new tables to support researcher information, experiments,
-- detector maintenance, detector calibration, and analysis results.
--
-- The original database tables are kept unchanged.
-- This file also includes sample data for the newly created tables.
--
-- New Tables:
-- 1. Researcher
-- 2. Experiment
-- 3. Detector_Maintenance
-- 4. Detector_Calibration
-- 5. AnalysisResult

-- Collider DB Team 09: Expansion tables with synthetic sample data
-- Run this AFTER the original collider_db.sql has been imported.
-- Recreates only the five expansion tables and inserts 500 records into each (2,500 total).
-- WARNING: Running this script again replaces the records in these five expansion tables.
-- Original seven tables and original data are not dropped or changed.


USE collider_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS analysisresult;
DROP TABLE IF EXISTS detector_calibration;
DROP TABLE IF EXISTS detector_maintenance;
DROP TABLE IF EXISTS experiment;
DROP TABLE IF EXISTS researcher;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE researcher (
 researcher_id INT AUTO_INCREMENT PRIMARY KEY,
 full_name VARCHAR(100) NOT NULL,
 email VARCHAR(150) UNIQUE,
 specialization VARCHAR(100),
 hire_date DATE
) ENGINE=InnoDB;

CREATE TABLE experiment (
 experiment_id INT AUTO_INCREMENT PRIMARY KEY,
 experiment_name VARCHAR(150) NOT NULL,
 researcher_id INT NOT NULL,
 start_date DATE,
 end_date DATE,
 status VARCHAR(30) NOT NULL DEFAULT 'Planned',
 description TEXT,
 CONSTRAINT fk_experiment_researcher FOREIGN KEY (researcher_id) REFERENCES researcher(researcher_id)
) ENGINE=InnoDB;

CREATE TABLE detector_maintenance (
 maintenance_id INT AUTO_INCREMENT PRIMARY KEY,
 detector_id INT NOT NULL,
 researcher_id INT NOT NULL,
 maintenance_date DATE NOT NULL,
 maintenance_type VARCHAR(100) NOT NULL,
 cost DECIMAL(12,2) DEFAULT 0.00,
 remarks TEXT,
 CONSTRAINT fk_maintenance_detector FOREIGN KEY (detector_id) REFERENCES detector(detector_id),
 CONSTRAINT fk_maintenance_researcher FOREIGN KEY (researcher_id) REFERENCES researcher(researcher_id)
) ENGINE=InnoDB;

CREATE TABLE detector_calibration (
 calibration_id INT AUTO_INCREMENT PRIMARY KEY,
 detector_id INT NOT NULL,
 calibration_date DATE NOT NULL,
 calibration_value DECIMAL(12,6) NOT NULL,
 expected_value DECIMAL(12,6) NOT NULL,
 status VARCHAR(30) NOT NULL,
 notes TEXT,
 CONSTRAINT fk_calibration_detector FOREIGN KEY (detector_id) REFERENCES detector(detector_id)
) ENGINE=InnoDB;

CREATE TABLE analysisresult (
 analysis_id INT AUTO_INCREMENT PRIMARY KEY,
 event_id INT NOT NULL,
 researcher_id INT NOT NULL,
 analysis_type VARCHAR(100) NOT NULL,
 result_value DECIMAL(15,6),
 result_date DATE NOT NULL,
 conclusion TEXT,
 CONSTRAINT fk_analysis_event FOREIGN KEY (event_id) REFERENCES collisionevent(event_id),
 CONSTRAINT fk_analysis_researcher FOREIGN KEY (researcher_id) REFERENCES researcher(researcher_id)
) ENGINE=InnoDB;

